-- Smoke harness for the AWR Capacity APEX app; generated by apex/build.py --smoke.
-- Run as the parsing schema:  @test/apex_smoke.sql [app_id]   (default 110)
-- Runs the page loader for every page and every region query of the app under
-- representative filter values in an APEX session; exits non-zero on any failure.
set serveroutput on size unlimited format wrapped feedback off verify off define on
whenever sqlerror exit failure rollback
column 1 new_value 1 noprint
select '' "1" from dual where rownum = 0;
variable app_id number
exec :app_id := nvl(to_number(trim('&1')), 110)
set define off
declare
  l_fail pls_integer := 0;
  procedure check_query(p_label in varchar2, p_sql in varchar2, p_must in boolean) is
    l_ctx apex_exec.t_context;
    l_rows number;
    l_t0 pls_integer := dbms_utility.get_time;
  begin
    l_ctx := apex_exec.open_query_context(p_location => apex_exec.c_location_local_db,
      p_sql_query => p_sql, p_auto_bind_items => true, p_total_row_count => true);
    l_rows := apex_exec.get_total_row_count(l_ctx);
    apex_exec.close(l_ctx);
    dbms_output.put_line(case when p_must and l_rows = 0 then 'FAIL ' else 'ok   ' end || lpad(l_rows, 6) || to_char((dbms_utility.get_time - l_t0) / 100, '990.00') || 's  ' || p_label);
    if p_must and l_rows = 0 then l_fail := l_fail + 1; end if;
  exception when others then
    apex_exec.close(l_ctx);
    dbms_output.put_line('FAIL  error  ' || p_label || ': ' || sqlerrm);
    l_fail := l_fail + 1;
  end;
  procedure check_empty(p_label in varchar2, p_sql in varchar2) is
    l_rows number;
  begin
    execute immediate 'select count(*) from (' || p_sql || ')' into l_rows;
    dbms_output.put_line(case when l_rows = 0 then 'ok   ' else 'FAIL ' end || lpad(l_rows, 6) || '  ' || p_label);
    if l_rows > 0 then l_fail := l_fail + 1; end if;
  end;
  procedure load_page(p_page in pls_integer, p_request in varchar2) is
  begin
    declare
      procedure load(p_name in varchar2, p_query in varchar2) is
      begin
        if not apex_collection.collection_exists(p_name) then
          apex_collection.create_collection_from_queryb2(
            p_collection_name => p_name, p_query => p_query, p_truncate_if_exists => 'YES');
        end if;
      end;
    begin
      if p_request = 'REFRESH' then
        if apex_collection.collection_exists('AWRCAP_CONTAINER') then apex_collection.delete_collection('AWRCAP_CONTAINER'); end if;
        if apex_collection.collection_exists('AWRCAP_SERIES') then apex_collection.delete_collection('AWRCAP_SERIES'); end if;
        if apex_collection.collection_exists('AWRCAP_FORECAST') then apex_collection.delete_collection('AWRCAP_FORECAST'); end if;
        if apex_collection.collection_exists('AWRCAP_FIT') then apex_collection.delete_collection('AWRCAP_FIT'); end if;
        if apex_collection.collection_exists('AWRCAP_ANOMALIES') then apex_collection.delete_collection('AWRCAP_ANOMALIES'); end if;
        if apex_collection.collection_exists('AWRCAP_ALERTS') then apex_collection.delete_collection('AWRCAP_ALERTS'); end if;
        if apex_collection.collection_exists('AWRCAP_META') then apex_collection.delete_collection('AWRCAP_META'); end if;
      end if;
      if p_page in (1, 2, 3, 4) then
        load('AWRCAP_CONTAINER', q'~select dbid, con_dbid, cast(null as number), cast(null as number), cast(null as number), cast(null as date), cast(null as date), cast(null as date), cast(null as date), cast(null as date), db_pdb, db_name, con_name from (select * from capr_container)~');
      end if;
      if p_page in (1, 2, 3, 4) then
        load('AWRCAP_SERIES', q'~select value, limit_value, expected, rate_bpd, anomaly, ts, cast(null as date), cast(null as date), cast(null as date), cast(null as date), db, kind, series, unit, anomaly_flag, to_char(round(pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(gap, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(z, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(threshold, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(delta_bytes, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(busy_p95, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(busy_peak_pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') from (select * from capr_series_points)~');
      end if;
      if p_page in (2, 3) then
        load('AWRCAP_FORECAST', q'~select value, lo, hi, limit_value, horizon_days, ts, cast(null as date), cast(null as date), cast(null as date), cast(null as date), db, kind, series, unit, method, quality, to_char(round(pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') from (select * from capr_forecast_points)~');
      end if;
      if p_page in (1, 2, 3) then
        load('AWRCAP_FIT', q'~select value, limit_value, pct, days_to_full, sev_rank, last_day, cast(null as date), cast(null as date), cast(null as date), cast(null as date), db, kind, series, unit, method, quality, sev, limit_source, to_char(round(slope_per_day, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(r2, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(days_to_full_lo, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(days_to_full_hi, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(accel, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(train_n, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') from (select * from capr_fit)~');
      end if;
      if p_page in (1, 2, 3, 4) then
        load('AWRCAP_ANOMALIES', q'~select value, expected, threshold, z, sev_rank, ts, obs_day, cast(null as date), cast(null as date), cast(null as date), db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, to_char(round(shift_pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(rate_bpd, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') from (select * from capr_anomalies)~');
      end if;
      if p_page in (1, 2, 3, 4) then
        load('AWRCAP_ALERTS', q'~select sev_rank, value, threshold, cast(null as number), cast(null as number), day_dt, cast(null as date), cast(null as date), cast(null as date), cast(null as date), severity, kind, db_pdb, series_key, unit, message from (select * from capr_alerts)~');
      end if;
      if p_page in (1, 2, 3, 4) then
        load('AWRCAP_META', q'~select cpu_sat_pct, dtf_warn, dtf_crit, nearfull_warn_pct, nearfull_crit_pct, loaded_at, cast(null as date), cast(null as date), cast(null as date), cast(null as date), to_char(round(series_sat_pct, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,'''), to_char(round(anomaly_report_days, 10), 'TM9', 'NLS_NUMERIC_CHARACTERS=''.,''') from (select max(case when cfg_name = 'cpu_sat_pct' then cfg_value end) cpu_sat_pct, max(case when cfg_name = 'dtf_warn' then cfg_value end) dtf_warn, max(case when cfg_name = 'dtf_crit' then cfg_value end) dtf_crit, max(case when cfg_name = 'nearfull_warn_pct' then cfg_value end) nearfull_warn_pct, max(case when cfg_name = 'nearfull_crit_pct' then cfg_value end) nearfull_crit_pct, max(case when cfg_name = 'series_sat_pct' then cfg_value end) series_sat_pct, max(case when cfg_name = 'anomaly_report_days' then cfg_value end) anomaly_report_days , sysdate loaded_at from cap_config)~');
      end if;
      if p_page in (1, 2, 3, 4) then
        if v('P0_FROM') is null or v('P0_TO') is null then
          for r in (with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
        select max(s.ts) last_day from c_series s) loop
            if v('P0_FROM') is null then apex_util.set_session_state('P0_FROM', to_char(r.last_day - 120, 'YYYY-MM-DD')); end if;
            if v('P0_TO') is null then apex_util.set_session_state('P0_TO', to_char(r.last_day + 120, 'YYYY-MM-DD')); end if;
          end loop;
        end if;
      end if;
      if p_page in (2) then
        if nvl(v('P0_TBSPC'), '-') <> 'ALL' then
          for r in (with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
        select max(f.db || '|' || f.series) keep (dense_rank first order by case when f.db || '|' || f.series = v('P0_TBSPC') then 0 else 1 end, f.days_to_full nulls last, f.pct desc nulls last) tbspc
        from c_fit f where f.kind = 'TBSPC' and (v('P0_DB') is null or f.db = v('P0_DB'))) loop
            apex_util.set_session_state('P0_TBSPC', r.tbspc);
          end loop;
        end if;
      end if;
    end;
  end load_page;
  procedure check_page_1(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c order by c.db_pdb~', false);
    check_query(q'~p0 Data~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where (:P0_DB is null or s.db = :P0_DB)) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where (:P0_DB is null or s.db = :P0_DB)) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where (:P0_DB is null or s.db = :P0_DB) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p1 Summary~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from apex_collections where collection_name = 'AWRCAP_ALERTS'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select (select count(*) from c_alert a where a.severity = 'CRIT' and (:P0_DB is null or a.db_pdb = :P0_DB)) CRIT, (select count(*) from c_alert a where a.severity = 'WARN' and (:P0_DB is null or a.db_pdb = :P0_DB)) WARN, (select count(*) from c_alert a where a.severity = 'INFO' and (:P0_DB is null or a.db_pdb = :P0_DB)) INFO, (select nvl(to_char(min(f.days_to_full)), '-') from c_fit f where f.kind = 'TBSPC' and (:P0_DB is null or f.db = :P0_DB)) DTF, (select count(*) from c_anom a, c_meta m where nvl(a.obs_day, a.ts) > (select max(s.ts) from c_series s) - m.anomaly_report_days and (:P0_DB is null or a.db = :P0_DB)) ANOM, (select round(sum(s.value), 1) from c_series s where s.kind = 'SERIES' and s.series = 'DB_SIZE_GB' and (:P0_DB is null or s.db = :P0_DB) and s.ts = (select max(x.ts) from c_series x where x.kind = 'SERIES' and x.series = 'DB_SIZE_GB' and x.db = s.db)) DB_GIB
from dual~', false);
    check_query(q'~p1 Current alerts~', q'~with c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from apex_collections where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, a.unit UNIT, a.message MESSAGE
from c_alert a where (:P0_DB is null or a.db_pdb = :P0_DB)~', p_demo);
    check_query(q'~p1 Worst days to full~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select f.db DB, f.series TABLESPACE, apex_page.get_url(p_page => 2, p_items => 'P0_DB,P0_TBSPC', p_values => f.db || ',' || f.db || '|' || f.series) TABLESPACE_URL, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.pct, 1) USED_PCT, f.days_to_full DTF
from c_fit f where f.kind = 'TBSPC' and (:P0_DB is null or f.db = :P0_DB)
order by f.days_to_full nulls last, f.pct desc nulls last fetch first 10 rows only~', false);
    check_query(q'~p1 Tablespace used % / Critical~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select case when :P0_DB is null then f.db || ' ' || f.series else f.series end label, round(f.pct, 1) value from c_fit f where f.kind = 'TBSPC' and f.sev = 'CRIT' and (:P0_DB is null or f.db = :P0_DB) order by f.pct desc~', false);
    check_query(q'~p1 Tablespace used % / Warning~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select case when :P0_DB is null then f.db || ' ' || f.series else f.series end label, round(f.pct, 1) value from c_fit f where f.kind = 'TBSPC' and f.sev = 'WARN' and (:P0_DB is null or f.db = :P0_DB) order by f.pct desc~', false);
    check_query(q'~p1 Tablespace used % / OK~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select case when :P0_DB is null then f.db || ' ' || f.series else f.series end label, round(f.pct, 1) value from c_fit f where f.kind = 'TBSPC' and f.sev not in ('CRIT', 'WARN') and (:P0_DB is null or f.db = :P0_DB) order by f.pct desc~', false);
  end check_page_1;
  procedure check_page_2(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c order by c.db_pdb~', false);
    check_query(q'~p0 P0_TBSPC lov~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select f.series || case when :P0_DB is null then ' (' || f.db || ')' end d, f.db || '|' || f.series r from c_fit f where f.kind = 'TBSPC' and (:P0_DB is null or f.db = :P0_DB) order by 1~', false);
    check_query(q'~p0 Data~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where (:P0_DB is null or s.db = :P0_DB)) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where (:P0_DB is null or s.db = :P0_DB)) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where (:P0_DB is null or s.db = :P0_DB) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p2 Tablespace summary~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT'),
c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select (select count(*) from c_fit f where f.kind = 'TBSPC' and f.sev = 'CRIT' and (:P0_DB is null or f.db = :P0_DB)) CRIT, (select count(*) from c_fit f where f.kind = 'TBSPC' and f.sev = 'WARN' and (:P0_DB is null or f.db = :P0_DB)) WARN, (select count(*) from c_anom a where a.kind = 'TBSPC' and (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts)) ANOM, (select nvl(to_char(min(f.days_to_full)), '-') from c_fit f where f.kind = 'TBSPC' and (:P0_DB is null or f.db = :P0_DB)) DTF
from dual~', false);
    check_query(q'~p2 Days to full~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select f.db DB, f.series TABLESPACE, apex_page.get_url(p_page => 2, p_items => 'P0_TBSPC', p_values => f.db || '|' || f.series) TABLESPACE_URL, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.pct, 1) USED_PCT, round(f.value / 1073741824, 2) USED_GIB, round(f.limit_value / 1073741824, 2) CEILING_GIB, round(f.slope_per_day / 1048576, 1) GROWTH_MIB, f.days_to_full DTF, f.days_to_full_lo DTF_LO, f.days_to_full_hi DTF_HI, round(f.r2, 3) R2, f.quality QUALITY, f.limit_source LIMIT_SOURCE
from c_fit f where f.kind = 'TBSPC' and (:P0_DB is null or f.db = :P0_DB)~', false);
    check_query(q'~p2 Used space / Used~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value / 1073741824, 2) value, case when :P0_TBSPC = 'ALL' then case when :P0_DB is null then s.db || ' ' || s.series else s.series end else 'Used GiB' end name from c_series s where s.kind = 'TBSPC' and (s.db || '|' || s.series = :P0_TBSPC or (:P0_TBSPC = 'ALL' and (:P0_DB is null or s.db = :P0_DB))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', p_demo);
    check_query(q'~p2 Used space / Forecast~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'REGR' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p2 Used space / Forecast low~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value) / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'REGR' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p2 Used space / Forecast high~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value) / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'REGR' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p2 Used space / Ceiling~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select e.ts, l.value from (select round(f.limit_value / 1073741824, 2) value from c_fit f where f.kind = 'TBSPC' and f.db || '|' || f.series = :P0_TBSPC) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p2 Used space / ESM +30~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value / 1073741824, 2) value from c_fcst f where f.kind = 'TBSPC' and f.method = 'ESM' and f.db || '|' || f.series = :P0_TBSPC and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts)~', false);
    check_query(q'~p2 Used space / Anomaly~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value / 1073741824, 2) value from c_series s where s.kind = 'TBSPC' and s.anomaly = 1 and (s.db || '|' || s.series = :P0_TBSPC or (:P0_TBSPC = 'ALL' and (:P0_DB is null or s.db = :P0_DB))) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Daily growth / Growth~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.rate_bpd / 1048576, 1) value from c_series s where s.kind = 'TBSPC' and s.db || '|' || s.series = :P0_TBSPC and nvl(s.anomaly, 0) = 0 and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Daily growth / Anomalous growth~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.rate_bpd / 1048576, 1) value from c_series s where s.kind = 'TBSPC' and s.db || '|' || s.series = :P0_TBSPC and s.anomaly = 1 and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Daily growth / Median rate~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.expected / 1048576, 1) value from c_series s where s.kind = 'TBSPC' and s.db || '|' || s.series = :P0_TBSPC and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p2 Growth anomalies~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select a.ts DAY, a.db DB, a.series TABLESPACE, apex_page.get_url(p_page => 2, p_items => 'P0_TBSPC', p_values => a.db || '|' || a.series) TABLESPACE_URL, a.anomaly_kind ANOMALY_KIND, a.sev SEV, case a.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(a.value / 1073741824, 2) GROWTH_GIB, round(a.rate_bpd / 1048576, 1) RATE_MIB, round(a.expected / 1048576, 1) MEDIAN_MIB, round(a.threshold / 1048576, 1) THRESHOLD_MIB, round(a.z, 1) Z, a.anomaly_flag FLAG, a.message MESSAGE
from c_anom a where a.kind = 'TBSPC' and (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts)~', false);
    check_query(q'~p2 Tablespace alerts~', q'~with c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from apex_collections where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, a.unit UNIT, a.message MESSAGE
from c_alert a where a.kind like 'TBSPC%' and (:P0_DB is null or a.db_pdb = :P0_DB)
order by a.sev_rank, a.day_dt desc~', false);
  end check_page_2;
  procedure check_page_3(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c order by c.db_pdb~', false);
    check_query(q'~p0 Data~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where (:P0_DB is null or s.db = :P0_DB)) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where (:P0_DB is null or s.db = :P0_DB)) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where (:P0_DB is null or s.db = :P0_DB) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p3 Host CPU busy % / Busy %~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 1) value, s.db || ' busy %' name from c_series s where s.kind = 'CPU' and s.series = 'BUSY_PCT' and (:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', p_demo);
    check_query(q'~p3 Host CPU busy % / Busy-hour p95~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.busy_p95, 1) value, s.db || ' busy-hour p95' name from c_series s where s.kind = 'CPU' and s.series = 'BUSY_PCT' and (:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 Host CPU busy % / Forecast~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value, 2) value, f.db || ' forecast' name from c_fcst f where f.kind = 'CPU' and f.method = 'REGR' and f.series = 'BUSY_P95' and (:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Host CPU busy % / Forecast low~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value), 2) value, f.db || ' forecast low' name from c_fcst f where f.kind = 'CPU' and f.method = 'REGR' and f.series = 'BUSY_P95' and (:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Host CPU busy % / Forecast high~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value), 2) value, f.db || ' forecast high' name from c_fcst f where f.kind = 'CPU' and f.method = 'REGR' and f.series = 'BUSY_P95' and (:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Host CPU busy % / Saturation~', q'~with c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select e.ts, l.value from (select m.cpu_sat_pct value from c_meta m) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p3 Host CPU busy % / Anomaly~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 1) value from c_series s where s.kind = 'CPU' and s.series = 'BUSY_PCT' and s.anomaly = 1 and (:P0_DB is null or s.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 DB CPU % of host per container / DB CPU %~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 1) value, s.db name from c_series s where s.kind = 'CPU' and s.series = 'DB_CPU_PCT' and (:P0_DB is null or s.db = :P0_DB) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 DB CPU % of host per container / Level shift~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select case k.n when 1 then a.ts else a.obs_day end ts, round(a.value, 1) value, 'Level shift ' || a.db || ' from ' || to_char(a.ts, 'YYYY-MM-DD') name from c_anom a cross join (select 1 n from dual union all select 2 n from dual) k where a.anomaly_kind = 'CPU_SHIFT' and (:P0_DB is null or a.db = :P0_DB) and a.obs_day between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.obs_day) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.obs_day) order by 3, 1~', false);
    check_query(q'~p3 CPU trend~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select f.db DB, f.series METRIC, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.value, 1) CURRENT_VALUE, f.unit UNIT, round(f.slope_per_day, 3) SLOPE, f.days_to_full DTS, f.days_to_full_lo DTS_LO, f.days_to_full_hi DTS_HI, round(f.r2, 3) R2, f.quality QUALITY
from c_fit f where f.kind = 'CPU' and (f.series in ('BUSY_PCT', 'BUSY_P95', 'BUSY_PEAK') and (:P0_DB is null or f.db in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)) or f.series not in ('BUSY_PCT', 'BUSY_P95', 'BUSY_PEAK') and (:P0_DB is null or f.db = :P0_DB))~', false);
    check_query(q'~p3 Sessions / Observed~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 2) value, s.db name from c_series s where s.kind = 'SERIES' and s.series = 'SESSIONS' and (:P0_DB is null or s.db = :P0_DB) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 Sessions / Forecast~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value, 2) value, f.db || ' forecast' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'SESSIONS' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Sessions / Forecast low~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value), 2) value, f.db || ' forecast low' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'SESSIONS' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Sessions / Forecast high~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value), 2) value, f.db || ' forecast high' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'SESSIONS' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Sessions / Limit~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select e.ts, l.value, l.db || ' limit' name from (select f.limit_value value, f.db from c_fit f where f.kind = 'SERIES' and f.series = 'SESSIONS' and (:P0_DB is null or f.db = :P0_DB)) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p3 Processes / Observed~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 2) value, s.db name from c_series s where s.kind = 'SERIES' and s.series = 'PROCESSES' and (:P0_DB is null or s.db = :P0_DB) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 Processes / Forecast~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
