    check_query(q'~p3 Database size (GiB) / Observed~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
