    check_query(q'~p3 Database size (GiB) / Forecast high~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value), 2) value, f.db || ' forecast high' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'DB_SIZE_GB' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Database size (GiB) / Limit~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select e.ts, l.value, l.db || ' limit' name from (select f.limit_value value, f.db from c_fit f where f.kind = 'SERIES' and f.series = 'DB_SIZE_GB' and (:P0_DB is null or f.db = :P0_DB)) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p3 Redo (GiB/day) / Observed~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select s.ts, round(s.value, 2) value, s.db name from c_series s where s.kind = 'SERIES' and s.series = 'REDO_GB_DAY' and (:P0_DB is null or s.db = :P0_DB) and s.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), s.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), s.ts) order by s.ts~', false);
    check_query(q'~p3 Redo (GiB/day) / Forecast~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(f.value, 2) value, f.db || ' forecast' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'REDO_GB_DAY' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Redo (GiB/day) / Forecast low~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.lo, f.value), 2) value, f.db || ' forecast low' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'REDO_GB_DAY' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Redo (GiB/day) / Forecast high~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select f.ts, round(nvl(f.hi, f.value), 2) value, f.db || ' forecast high' name from c_fcst f where f.kind = 'SERIES' and f.method = 'REGR' and f.series = 'REDO_GB_DAY' and (:P0_DB is null or f.db = :P0_DB) and f.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), f.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), f.ts) order by f.ts~', false);
    check_query(q'~p3 Redo (GiB/day) / Limit~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select e.ts, l.value, l.db || ' limit' name from (select f.limit_value value, f.db from c_fit f where f.kind = 'SERIES' and f.series = 'REDO_GB_DAY' and (:P0_DB is null or f.db = :P0_DB)) l cross join (select to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD') ts from dual union all select to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD') ts from dual) e where e.ts is not null and l.value is not null order by e.ts~', false);
    check_query(q'~p3 Workload fits~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select f.db DB, f.series SERIES, f.sev SEV, case f.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, round(f.value, 2) CURRENT_VALUE, f.unit UNIT, round(f.limit_value, 2) LIMIT_VALUE, round(f.pct, 1) PCT, f.days_to_full DTL, round(f.slope_per_day, 3) SLOPE, round(f.r2, 3) R2, f.quality QUALITY
from c_fit f where f.kind = 'SERIES' and (:P0_DB is null or f.db = :P0_DB)~', false);
    check_query(q'~p3 CPU and series alerts~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER'),
c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from apex_collections where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, a.unit UNIT, a.message MESSAGE
from c_alert a where a.kind not like 'TBSPC%' and ((:P0_DB is null or a.db_pdb = :P0_DB) or (:P0_DB is null or a.db_pdb in (select r.db_pdb from c_cont r, c_cont c where c.db_pdb = :P0_DB and r.dbid = c.dbid and r.con_dbid = r.dbid)))
order by a.sev_rank, a.day_dt desc~', false);
  end check_page_3;
  procedure check_page_4(p_demo in boolean) is
  begin
    check_query(q'~p0 P0_DB lov~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER')
select c.db_pdb d, c.db_pdb r from c_cont c order by c.db_pdb~', false);
    check_query(q'~p0 P0_KIND lov~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select a.anomaly_kind d, a.anomaly_kind r from c_anom a group by a.anomaly_kind order by 1~', false);
    check_query(q'~p0 P0_SEV lov~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select a.sev d, a.sev r from c_anom a group by a.sev order by min(a.sev_rank)~', false);
    check_query(q'~p0 Data~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES'),
c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select (select count(distinct s.db) from c_series s where (:P0_DB is null or s.db = :P0_DB)) DATABASES, (select to_char(max(s.ts), 'YYYY-MM-DD') from c_series s where (:P0_DB is null or s.db = :P0_DB)) LATEST, (select to_char(min(l.ts), 'YYYY-MM-DD') from (select max(s.ts) ts from c_series s where (:P0_DB is null or s.db = :P0_DB) group by s.db) l) STALEST, (select to_char(m.loaded_at, 'HH24:MI') from c_meta m) LOADED
from dual~', p_demo);
    check_query(q'~p4 Anomaly summary~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select (select count(*) from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) ANOMALIES, (select count(distinct a.db) from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) DATABASES, (select count(distinct a.db || '|' || a.series) from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) SERIES, (select count(*) from c_anom a where a.sev in ('WARN', 'CRIT') and (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) SERIOUS
from dual~', false);
    check_query(q'~p4 Anomalies per day by kind / Anomalies~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select a.ts, count(*) value, a.anomaly_kind name from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV) group by a.ts, a.anomaly_kind order by a.ts~', p_demo);
    check_query(q'~p4 Most anomalous series / Anomalies~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select a.db || ' ' || a.series label, count(*) value from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV) group by a.db, a.series order by count(*) desc, 1 fetch first 10 rows only~', false);
    check_query(q'~p4 Anomaly timeline / Anomalies~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select e.db || ' ' || e.series || ': ' || e.anomaly_kind || case when e.n > 1 then ' (' || e.n || ' days)' end task_name, e.db || '|' || e.series || '|' || e.anomaly_kind || '|' || to_char(e.start_date, 'YYYYMMDD') task_id, e.start_date, e.end_date, e.anomaly_kind kind, nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), min(e.start_date) over ()) gantt_start, nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), max(e.end_date) over ()) gantt_end
from (select a.db, a.series, a.anomaly_kind, min(a.ts) start_date, max(nvl(a.obs_day, a.ts)) + 1 end_date, count(*) n from (select a.*, a.ts - dense_rank() over (partition by a.db, a.series, a.anomaly_kind order by a.ts) grp from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)) a group by a.db, a.series, a.anomaly_kind, a.grp) e
order by e.db, e.series, e.start_date~', false);
    check_query(q'~p4 Anomalies~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select a.ts DAY, a.obs_day END_DAY, a.db DB, apex_page.get_url(p_page => case a.kind when 'TBSPC' then 2 else 3 end, p_items => 'P0_DB', p_values => a.db) DB_URL, a.series SERIES, apex_page.get_url(p_page => case a.kind when 'TBSPC' then 2 else 3 end, p_items => 'P0_DB,P0_TBSPC', p_values => a.db || ',' || case when a.kind = 'TBSPC' then a.db || '|' || a.series end) SERIES_URL, a.anomaly_kind ANOMALY_KIND, a.sev SEV, case a.sev when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.anomaly_flag FLAG, round(a.value, 2) VALUE, round(a.expected, 2) EXPECTED, round(a.threshold, 2) THRESHOLD, round(a.z, 1) Z, round(a.shift_pct, 1) SHIFT_PCT, a.unit UNIT, a.message MESSAGE
from c_anom a where (:P0_DB is null or a.db = :P0_DB) and a.ts between nvl(to_date(:P0_FROM default null on conversion error, 'YYYY-MM-DD'), a.ts) and nvl(to_date(:P0_TO default null on conversion error, 'YYYY-MM-DD'), a.ts) and (:P0_KIND is null or a.anomaly_kind = :P0_KIND) and (:P0_SEV is null or a.sev = :P0_SEV)~', p_demo);
    check_query(q'~p4 All alerts~', q'~with c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from apex_collections where collection_name = 'AWRCAP_ALERTS')
select a.severity SEV, case a.severity when 'CRIT' then 't-Badge--danger' when 'WARN' then 't-Badge--warning' when 'INFO' then 't-Badge--info' else 't-Badge--success' end SEV_CSS, a.sev_rank SEV_RANK, a.kind KIND, a.db_pdb DB, a.series_key SERIES, a.day_dt DAY, round(a.value, 2) VALUE, round(a.threshold, 2) THRESHOLD, a.unit UNIT, a.message MESSAGE
from c_alert a where (:P0_DB is null or a.db_pdb = :P0_DB) and (:P0_SEV is null or a.severity = :P0_SEV)
order by a.sev_rank, a.day_dt desc~', false);
  end check_page_4;
begin
  apex_session.create_session(p_app_id => :app_id, p_page_id => 1, p_username => 'AWRCAP_VIEWER');
  dbms_output.put_line('-- scenario defaults');
  apex_util.set_session_state('P0_DB', null);
  apex_util.set_session_state('P0_TBSPC', null);
  apex_util.set_session_state('P0_FROM', null);
  apex_util.set_session_state('P0_TO', null);
  apex_util.set_session_state('P0_KIND', null);
  apex_util.set_session_state('P0_SEV', null);
  load_page(1, q'~REFRESH~');
  dbms_output.put_line('page 1: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_1(true);
  load_page(2, null);
  dbms_output.put_line('page 2: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_2(true);
  load_page(3, null);
  dbms_output.put_line('page 3: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_3(true);
  load_page(4, null);
  dbms_output.put_line('page 4: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_4(true);
  dbms_output.put_line('-- scenario pdb');
  apex_util.set_session_state('P0_DB', q'~ECOMPRD/SHOP_PDB~');
  apex_util.set_session_state('P0_TBSPC', q'~ECOMPRD/SHOP_PDB|AUDIT_TRAIL~');
  apex_util.set_session_state('P0_FROM', null);
  apex_util.set_session_state('P0_TO', null);
  apex_util.set_session_state('P0_KIND', null);
  apex_util.set_session_state('P0_SEV', null);
  load_page(1, null);
  dbms_output.put_line('page 1: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_1(true);
  load_page(2, null);
  dbms_output.put_line('page 2: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_2(true);
  load_page(3, null);
  dbms_output.put_line('page 3: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_3(true);
  load_page(4, null);
  dbms_output.put_line('page 4: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_4(true);
  dbms_output.put_line('-- scenario cdb-all-tbspc');
  apex_util.set_session_state('P0_DB', q'~ECOMPRD~');
  apex_util.set_session_state('P0_TBSPC', q'~ALL~');
  apex_util.set_session_state('P0_FROM', null);
  apex_util.set_session_state('P0_TO', null);
  apex_util.set_session_state('P0_KIND', null);
  apex_util.set_session_state('P0_SEV', null);
  load_page(1, null);
  dbms_output.put_line('page 1: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_1(false);
  load_page(2, null);
  dbms_output.put_line('page 2: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_2(false);
  load_page(3, null);
  dbms_output.put_line('page 3: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_3(false);
  load_page(4, null);
  dbms_output.put_line('page 4: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_4(false);
  dbms_output.put_line('-- scenario filtered');
  apex_util.set_session_state('P0_DB', null);
  apex_util.set_session_state('P0_TBSPC', null);
  apex_util.set_session_state('P0_FROM', null);
  apex_util.set_session_state('P0_TO', null);
  apex_util.set_session_state('P0_KIND', q'~TBSPC_GROWTH~');
  apex_util.set_session_state('P0_SEV', q'~WARN~');
  load_page(1, null);
  dbms_output.put_line('page 1: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_1(false);
  load_page(2, null);
  dbms_output.put_line('page 2: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_2(false);
  load_page(3, null);
  dbms_output.put_line('page 3: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_3(false);
  load_page(4, null);
  dbms_output.put_line('page 4: P0_TBSPC=' || v('P0_TBSPC') || ' P0_FROM=' || v('P0_FROM') || ' P0_TO=' || v('P0_TO'));
  check_page_4(false);
  dbms_output.put_line('-- collection fidelity (decoded collection vs source view)');
  check_empty(q'~AWRCAP_CONTAINER~', q'~with c_cont as (select c001 db_pdb, c002 db_name, c003 con_name, n001 dbid, n002 con_dbid from apex_collections where collection_name = 'AWRCAP_CONTAINER')
select * from ((select db_pdb, db_name, con_name, round(dbid, 10), round(con_dbid, 10) from c_cont minus select db_pdb, db_name, con_name, round(dbid, 10), round(con_dbid, 10) from (select * from capr_container))
union all (select db_pdb, db_name, con_name, round(dbid, 10), round(con_dbid, 10) from (select * from capr_container) minus select db_pdb, db_name, con_name, round(dbid, 10), round(con_dbid, 10) from c_cont))~');
  check_empty(q'~AWRCAP_SERIES~', q'~with c_series as (select c001 db, c002 kind, c003 series, c004 unit, c005 anomaly_flag, d001 ts, n001 value, n002 limit_value, n003 expected, n004 rate_bpd, n005 anomaly, to_number(c006, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') gap, to_number(c008, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') z, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') threshold, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') delta_bytes, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_p95, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') busy_peak_pct from apex_collections where collection_name = 'AWRCAP_SERIES')
select * from ((select db, kind, series, unit, anomaly_flag, ts, round(value, 10), round(limit_value, 10), round(expected, 10), round(rate_bpd, 10), round(anomaly, 10), round(pct, 10), round(gap, 10), round(z, 10), round(threshold, 10), round(delta_bytes, 10), round(busy_p95, 10), round(busy_peak_pct, 10) from c_series minus select db, kind, series, unit, anomaly_flag, ts, round(value, 10), round(limit_value, 10), round(expected, 10), round(rate_bpd, 10), round(anomaly, 10), round(pct, 10), round(gap, 10), round(z, 10), round(threshold, 10), round(delta_bytes, 10), round(busy_p95, 10), round(busy_peak_pct, 10) from (select * from capr_series_points))
union all (select db, kind, series, unit, anomaly_flag, ts, round(value, 10), round(limit_value, 10), round(expected, 10), round(rate_bpd, 10), round(anomaly, 10), round(pct, 10), round(gap, 10), round(z, 10), round(threshold, 10), round(delta_bytes, 10), round(busy_p95, 10), round(busy_peak_pct, 10) from (select * from capr_series_points) minus select db, kind, series, unit, anomaly_flag, ts, round(value, 10), round(limit_value, 10), round(expected, 10), round(rate_bpd, 10), round(anomaly, 10), round(pct, 10), round(gap, 10), round(z, 10), round(threshold, 10), round(delta_bytes, 10), round(busy_p95, 10), round(busy_peak_pct, 10) from c_series))~');
  check_empty(q'~AWRCAP_FORECAST~', q'~with c_fcst as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, d001 ts, n001 value, n002 lo, n003 hi, n004 limit_value, n005 horizon_days, to_number(c007, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') pct from apex_collections where collection_name = 'AWRCAP_FORECAST')
select * from ((select db, kind, series, unit, method, quality, ts, round(value, 10), round(lo, 10), round(hi, 10), round(limit_value, 10), round(horizon_days, 10), round(pct, 10) from c_fcst minus select db, kind, series, unit, method, quality, ts, round(value, 10), round(lo, 10), round(hi, 10), round(limit_value, 10), round(horizon_days, 10), round(pct, 10) from (select * from capr_forecast_points))
union all (select db, kind, series, unit, method, quality, ts, round(value, 10), round(lo, 10), round(hi, 10), round(limit_value, 10), round(horizon_days, 10), round(pct, 10) from (select * from capr_forecast_points) minus select db, kind, series, unit, method, quality, ts, round(value, 10), round(lo, 10), round(hi, 10), round(limit_value, 10), round(horizon_days, 10), round(pct, 10) from c_fcst))~');
  check_empty(q'~AWRCAP_FIT~', q'~with c_fit as (select c001 db, c002 kind, c003 series, c004 unit, c005 method, c006 quality, c007 sev, c008 limit_source, d001 last_day, n001 value, n002 limit_value, n003 pct, n004 days_to_full, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') slope_per_day, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') r2, to_number(c011, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_lo, to_number(c012, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') days_to_full_hi, to_number(c013, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') accel, to_number(c014, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') train_n from apex_collections where collection_name = 'AWRCAP_FIT')
select * from ((select db, kind, series, unit, method, quality, sev, limit_source, last_day, round(value, 10), round(limit_value, 10), round(pct, 10), round(days_to_full, 10), round(sev_rank, 10), round(slope_per_day, 10), round(r2, 10), round(days_to_full_lo, 10), round(days_to_full_hi, 10), round(accel, 10), round(train_n, 10) from c_fit minus select db, kind, series, unit, method, quality, sev, limit_source, last_day, round(value, 10), round(limit_value, 10), round(pct, 10), round(days_to_full, 10), round(sev_rank, 10), round(slope_per_day, 10), round(r2, 10), round(days_to_full_lo, 10), round(days_to_full_hi, 10), round(accel, 10), round(train_n, 10) from (select * from capr_fit))
union all (select db, kind, series, unit, method, quality, sev, limit_source, last_day, round(value, 10), round(limit_value, 10), round(pct, 10), round(days_to_full, 10), round(sev_rank, 10), round(slope_per_day, 10), round(r2, 10), round(days_to_full_lo, 10), round(days_to_full_hi, 10), round(accel, 10), round(train_n, 10) from (select * from capr_fit) minus select db, kind, series, unit, method, quality, sev, limit_source, last_day, round(value, 10), round(limit_value, 10), round(pct, 10), round(days_to_full, 10), round(sev_rank, 10), round(slope_per_day, 10), round(r2, 10), round(days_to_full_lo, 10), round(days_to_full_hi, 10), round(accel, 10), round(train_n, 10) from c_fit))~');
  check_empty(q'~AWRCAP_ANOMALIES~', q'~with c_anom as (select c001 db, c002 kind, c003 series, c004 anomaly_kind, c005 anomaly_flag, c006 unit, c007 sev, c008 message, d001 ts, d002 obs_day, n001 value, n002 expected, n003 threshold, n004 z, n005 sev_rank, to_number(c009, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') shift_pct, to_number(c010, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') rate_bpd from apex_collections where collection_name = 'AWRCAP_ANOMALIES')
select * from ((select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from c_anom minus select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from (select * from capr_anomalies))
union all (select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from (select * from capr_anomalies) minus select db, kind, series, anomaly_kind, anomaly_flag, unit, sev, message, ts, obs_day, round(value, 10), round(expected, 10), round(threshold, 10), round(z, 10), round(sev_rank, 10), round(shift_pct, 10), round(rate_bpd, 10) from c_anom))~');
  check_empty(q'~AWRCAP_ALERTS~', q'~with c_alert as (select c001 severity, c002 kind, c003 db_pdb, c004 series_key, c005 unit, c006 message, d001 day_dt, n001 sev_rank, n002 value, n003 threshold from apex_collections where collection_name = 'AWRCAP_ALERTS')
select * from ((select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from c_alert minus select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from (select * from capr_alerts))
union all (select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from (select * from capr_alerts) minus select severity, kind, db_pdb, series_key, unit, message, day_dt, round(sev_rank, 10), round(value, 10), round(threshold, 10) from c_alert))~');
  check_empty(q'~AWRCAP_META~', q'~with c_meta as (select n001 cpu_sat_pct, n002 dtf_warn, n003 dtf_crit, n004 nearfull_warn_pct, n005 nearfull_crit_pct, to_number(c001, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') series_sat_pct, to_number(c002, '99999999999999999999999999D9999999999', 'NLS_NUMERIC_CHARACTERS=''.,''') anomaly_report_days, d001 loaded_at from apex_collections where collection_name = 'AWRCAP_META')
select * from ((select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from c_meta minus select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from (select max(case when cfg_name = 'cpu_sat_pct' then cfg_value end) cpu_sat_pct, max(case when cfg_name = 'dtf_warn' then cfg_value end) dtf_warn, max(case when cfg_name = 'dtf_crit' then cfg_value end) dtf_crit, max(case when cfg_name = 'nearfull_warn_pct' then cfg_value end) nearfull_warn_pct, max(case when cfg_name = 'nearfull_crit_pct' then cfg_value end) nearfull_crit_pct, max(case when cfg_name = 'series_sat_pct' then cfg_value end) series_sat_pct, max(case when cfg_name = 'anomaly_report_days' then cfg_value end) anomaly_report_days , sysdate loaded_at from cap_config))
union all (select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from (select max(case when cfg_name = 'cpu_sat_pct' then cfg_value end) cpu_sat_pct, max(case when cfg_name = 'dtf_warn' then cfg_value end) dtf_warn, max(case when cfg_name = 'dtf_crit' then cfg_value end) dtf_crit, max(case when cfg_name = 'nearfull_warn_pct' then cfg_value end) nearfull_warn_pct, max(case when cfg_name = 'nearfull_crit_pct' then cfg_value end) nearfull_crit_pct, max(case when cfg_name = 'series_sat_pct' then cfg_value end) series_sat_pct, max(case when cfg_name = 'anomaly_report_days' then cfg_value end) anomaly_report_days , sysdate loaded_at from cap_config) minus select round(cpu_sat_pct, 10), round(dtf_warn, 10), round(dtf_crit, 10), round(nearfull_warn_pct, 10), round(nearfull_crit_pct, 10), round(series_sat_pct, 10), round(anomaly_report_days, 10) from c_meta))~');
  for c in (select collection_name, count(*) n from apex_collections group by collection_name order by 1) loop
    dbms_output.put_line('collection ' || rpad(c.collection_name, 20) || lpad(c.n, 7));
  end loop;
  apex_session.delete_session;
  if l_fail > 0 then
    raise_application_error(-20001, l_fail || ' smoke check(s) failed');
  end if;
  dbms_output.put_line('smoke: all checks passed');
end;
/
undefine 1
exit
